public sealed record PurchaseListDto(Guid PurchaseInvoiceId,string InvoiceNumber,string? SupplierInvoiceNo,DateTimeOffset InvoiceDate,string SupplierName,string WarehouseName,decimal GrandTotal,decimal PaidAmount,decimal BalanceAmount,string Status);public sealed record PurchaseItemDto(Guid PurchaseItemId,Guid ProductId,string ProductCode,string ProductName,string? Barcode,string? BatchNo,DateOnly? ExpiryDate,decimal Quantity,decimal FreeQuantity,decimal ReturnedQuantity,decimal PurchasePrice,decimal MRP,decimal SellingPrice,decimal DiscountPercentage,decimal DiscountAmount,decimal GSTPercentage,decimal GSTAmount,decimal LineTotal);public sealed record PurchaseDto(Guid PurchaseInvoiceId,string InvoiceNumber,Guid SupplierId,string SupplierName,string? SupplierInvoiceNo,DateTimeOffset InvoiceDate,DateTimeOffset? DueDate,Guid WarehouseId,string WarehouseName,decimal Subtotal,decimal DiscountAmount,decimal TaxAmount,decimal ExpenseAmount,decimal RoundOff,decimal GrandTotal,decimal PaidAmount,decimal BalanceAmount,string Status,string? Remarks,IReadOnlyCollection<PurchaseItemDto> Items);public sealed record PagedPurchases(IReadOnlyCollection<PurchaseListDto> Items,int TotalCount,int PageNumber,int PageSize);public sealed record PurchaseDashboardDto(decimal TodayPurchases,int TodayCount,decimal Outstanding,decimal MonthPurchases);public sealed record PostedPurchaseDto(Guid PurchaseInvoiceId,string InvoiceNumber,decimal GrandTotal,decimal PaidAmount,decimal BalanceAmount,string Status);
