public sealed class PurchaseInputValidator:AbstractValidator<PurchaseInput>{public PurchaseInputValidator(){RuleFor(x=>x.SupplierId).NotEmpty();RuleFor(x=>x.WarehouseId).NotEmpty();RuleFor(x=>x.Items).NotEmpty();RuleForEach(x=>x.Items).SetValidator(new PurchaseItemValidator());RuleFor(x=>x.Status).Must(x=>x is"DRAFT"or"POSTED");RuleForEach(x=>x.Payments).ChildRules(x=>{x.RuleFor(p=>p.Amount).GreaterThan(0);x.RuleFor(p=>p.MethodCode).NotEmpty();});}}
public sealed class PurchaseItemValidator:AbstractValidator<PurchaseItemInput>{public PurchaseItemValidator(){RuleFor(x=>x.ProductId).NotEmpty();RuleFor(x=>x.Quantity).GreaterThan(0);RuleFor(x=>x.FreeQuantity).GreaterThanOrEqualTo(0);RuleFor(x=>x.PurchasePrice).GreaterThanOrEqualTo(0);RuleFor(x=>x.MRP).GreaterThanOrEqualTo(x=>x.SellingPrice);RuleFor(x=>x.GSTPercentage).InclusiveBetween(0,100);RuleFor(x=>x.DiscountPercentage).InclusiveBetween(0,100);}}
public sealed class PurchaseHandlers(IPurchaseRepository repository,IPurchaseEngine engine,IPurchaseSpreadsheetService sheets,ICurrentUserService user):IRequestHandler<GetPurchases,PagedPurchases>,IRequestHandler<GetPurchase,PurchaseDto>,IRequestHandler<CreatePurchase,PostedPurchaseDto>,IRequestHandler<UpdatePurchase,PurchaseDto>,IRequestHandler<DeletePurchase>,IRequestHandler<AddPurchasePayment>,IRequestHandler<ReturnPurchase>,IRequestHandler<GetPurchaseDashboard,PurchaseDashboardDto>,IRequestHandler<ExportPurchases,byte[]>,IRequestHandler<PurchaseTemplate,byte[]>{public async Task<PagedPurchases> Handle(GetPurchases q,CancellationToken t){var(x,n)=await repository.List(q.Search,q.Status,q.SupplierId,q.From,q.To,q.PageNumber,q.PageSize,t);return new(x.Select(List).ToArray(),n,q.PageNumber,q.PageSize);}public async Task<PurchaseDto> Handle(GetPurchase q,CancellationToken t)=>Map(await repository.Get(q.Id,false,t)??throw new EntityNotFoundException("Purchase not found."));public async Task<PostedPurchaseDto> Handle(CreatePurchase q,CancellationToken t){var i=q.Input;var r=await engine.Post(new(i.SupplierId,i.SupplierInvoiceNo,i.InvoiceDate,i.DueDate,i.WarehouseId,JsonSerializer.Serialize(i.Items),JsonSerializer.Serialize(i.Expenses),JsonSerializer.Serialize(i.Payments),i.BillDiscount,i.RoundOff,i.Remarks,i.Status,user.Username),t);return new(r.PurchaseInvoiceId,r.InvoiceNumber,r.GrandTotal,r.PaidAmount,r.BalanceAmount,r.Status);}public async Task<PurchaseDto> Handle(UpdatePurchase q,CancellationToken t){var p=await repository.Get(q.Id,true,t)??throw new EntityNotFoundException("Purchase not found.");if(p.Status!="DRAFT")throw new BusinessRuleException("Only draft purchases can be edited.");ApplyDraft(p,q.Input);p.ModifiedOn=DateTimeOffset.UtcNow;p.ModifiedBy=user.Username;await repository.Save(t);return Map(await repository.Get(q.Id,false,t)??p);}public async Task Handle(DeletePurchase q,CancellationToken t){var p=await repository.Get(q.Id,true,t)??throw new EntityNotFoundException("Purchase not found.");if(p.Status!="DRAFT")throw new BusinessRuleException("Only draft purchases can be deleted.");p.IsDeleted=true;p.ModifiedOn=DateTimeOffset.UtcNow;p.ModifiedBy=user.Username;await repository.Save(t);}public Task Handle(AddPurchasePayment q,CancellationToken t)=>engine.Pay(new(q.Input.PurchaseInvoiceId,q.Input.MethodCode,q.Input.Amount,q.Input.ReferenceNumber,user.Username),t);public Task Handle(ReturnPurchase q,CancellationToken t)=>engine.Return(new(q.Input.PurchaseInvoiceId,JsonSerializer.Serialize(q.Input.Items),q.Input.Reason,user.Username),t);public async Task<PurchaseDashboardDto> Handle(GetPurchaseDashboard q,CancellationToken t){var x=await repository.Dashboard(t);return new(x.TodayPurchases,x.TodayCount,x.Outstanding,x.MonthPurchases);}public async Task<byte[]> Handle(ExportPurchases q,CancellationToken t){var(x,_)=await repository.List(null,null,null,null,null,1,10000,t);return sheets.Export(x);}public Task<byte[]> Handle(PurchaseTemplate q,CancellationToken t)=>Task.FromResult(sheets.Template());private static PurchaseListDto List(PurchaseInvoice x)=>new(x.PurchaseInvoiceId,x.InvoiceNumber,x.SupplierInvoiceNo,x.InvoiceDate,x.Supplier.SupplierName,x.Warehouse.WarehouseName,x.GrandTotal,x.PaidAmount,x.BalanceAmount,x.Status);private static PurchaseDto Map(PurchaseInvoice x)=>new(x.PurchaseInvoiceId,x.InvoiceNumber,x.SupplierId,x.Supplier.SupplierName,x.SupplierInvoiceNo,x.InvoiceDate,x.DueDate,x.WarehouseId,x.Warehouse.WarehouseName,x.Subtotal,x.DiscountAmount,x.TaxAmount,x.ExpenseAmount,x.RoundOff,x.GrandTotal,x.PaidAmount,x.BalanceAmount,x.Status,x.Remarks,x.Items.Select(i=>new PurchaseItemDto(i.PurchaseItemId,i.ProductId,i.Product.ProductCode,i.Product.ProductName,i.Barcode,i.BatchNo,i.ExpiryDate,i.Quantity,i.FreeQuantity,i.ReturnedQuantity,i.PurchasePrice,i.MRP,i.SellingPrice,i.DiscountPercentage,i.DiscountAmount,i.GSTPercentage,i.GSTAmount,i.LineTotal)).ToArray());private static void ApplyDraft(PurchaseInvoice p,PurchaseInput i){p.SupplierId=i.SupplierId;p.SupplierInvoiceNo=i.SupplierInvoiceNo;p.InvoiceDate=i.InvoiceDate;p.DueDate=i.DueDate;p.WarehouseId=i.WarehouseId;p.Remarks=i.Remarks;p.Items.Clear();foreach(var x in i.Items){var discount=x.DiscountAmount>0?x.DiscountAmount:x.Quantity*x.PurchasePrice*x.DiscountPercentage/100;var gst=(x.Quantity*x.PurchasePrice-discount)*x.GSTPercentage/100;p.Items.Add(new(){ProductId=x.ProductId,Barcode=x.Barcode,BatchNo=x.BatchNo,ExpiryDate=x.ExpiryDate,Quantity=x.Quantity,FreeQuantity=x.FreeQuantity,PurchasePrice=x.PurchasePrice,MRP=x.MRP,SellingPrice=x.SellingPrice,DiscountPercentage=x.DiscountPercentage,DiscountAmount=discount,GSTPercentage=x.GSTPercentage,GSTAmount=gst,LineTotal=x.Quantity*x.PurchasePrice-discount+gst});}p.Subtotal=p.Items.Sum(x=>x.Quantity*x.PurchasePrice);p.DiscountAmount=p.Items.Sum(x=>x.DiscountAmount)+i.BillDiscount;p.TaxAmount=p.Items.Sum(x=>x.GSTAmount);p.ExpenseAmount=i.Expenses.Sum(x=>x.Amount);p.RoundOff=i.RoundOff;p.GrandTotal=p.Subtotal-p.DiscountAmount+p.TaxAmount+p.ExpenseAmount+p.RoundOff;}}
